package com.medicarepro;
import javax.swing.*; import java.awt.*;
public final class MainFrame {
 private final AuthService auth;private final ClinicRepository repo;public MainFrame(Database db){auth=new AuthService(db);repo=new ClinicRepository(db);}
 public void showLogin(){JFrame f=new JFrame("MediCare Pro - Login");f.setDefaultCloseOperation(3);JTextField u=new JTextField();JPasswordField p=new JPasswordField();JButton b=new JButton("Login");JPanel x=form("MediCare Pro",new JLabel("Username"),u,new JLabel("Password"),p,b);f.setContentPane(x);b.addActionListener(e->run(f,()->{AuthService.User a=auth.login(u.getText(),p.getPassword());if(a==null)throw new IllegalArgumentException("Invalid username or password.");f.dispose();dashboard(a);}));f.getRootPane().setDefaultButton(b);f.setSize(430,260);f.setLocationRelativeTo(null);f.setVisible(true);try{if(!auth.hasHeadDoctor())account(f,null,true);}catch(Exception e){error(f,e);}}
 private void dashboard(AuthService.User a){JFrame f=new JFrame("MediCare Pro - "+a.name());f.setDefaultCloseOperation(3);f.setSize(1000,620);f.setLocationRelativeTo(null);JTextField search=new JTextField();DefaultListModel<ClinicRepository.Patient> m=new DefaultListModel<>();JList<ClinicRepository.Patient> list=new JList<>(m);JButton load=new JButton("Search"),add=new JButton("Add"),edit=new JButton("Edit"),del=new JButton("Delete"),out=new JButton("Logout");JPanel top=new JPanel(new BorderLayout(8,8));top.add(new JLabel(a.headDoctor()?"HEAD DOCTOR - All patients":"USER - My patients"),BorderLayout.WEST);top.add(search);top.add(load,BorderLayout.EAST);JPanel buttons=new JPanel();buttons.add(add);buttons.add(edit);buttons.add(del);if(a.headDoctor()){JButton users=new JButton("Add user");buttons.add(users);users.addActionListener(e->account(f,a,false));}buttons.add(out);f.add(top,BorderLayout.NORTH);f.add(new JScrollPane(list));f.add(buttons,BorderLayout.SOUTH);Runnable refresh=()->run(f,()->{m.clear();for(var p:repo.patients(a,search.getText()))m.addElement(p);});load.addActionListener(e->refresh.run());search.addActionListener(e->refresh.run());add.addActionListener(e->patient(f,a,null,refresh));edit.addActionListener(e->{if(list.getSelectedValue()!=null)patient(f,a,list.getSelectedValue(),refresh);});del.addActionListener(e->{var p=list.getSelectedValue();if(p!=null&&JOptionPane.showConfirmDialog(f,"Delete "+p.name()+"?","Confirm",1)==0)run(f,()->{repo.delete(a,p.id());refresh.run();});});out.addActionListener(e->{f.dispose();showLogin();});list.setCellRenderer(new DefaultListCellRenderer(){public Component getListCellRendererComponent(JList<?>l,Object v,int i,boolean s,boolean z){var p=(ClinicRepository.Patient)v;return super.getListCellRendererComponent(l,"#"+p.id()+"  "+p.name()+" | "+p.age()+" | "+p.contact()+" | "+p.status(),i,s,z);}});f.setVisible(true);refresh.run();}
 private void patient(JFrame f,AuthService.User a,ClinicRepository.Patient old,Runnable refresh){JTextField n=new JTextField(old==null?"":old.name()),age=new JTextField(old==null?"":(""+old.age())),c=new JTextField(old==null?"":old.contact()),d=new JTextField(old==null?"":old.doctor()),x=new JTextField(old==null?"":old.diagnosis()),s=new JTextField(old==null?"Active":old.status());JPanel p=form(old==null?"Add patient":"Edit patient",new JLabel("Name"),n,new JLabel("Age"),age,new JLabel("Contact"),c,new JLabel("Doctor"),d,new JLabel("Diagnosis"),x,new JLabel("Status"),s);if(JOptionPane.showConfirmDialog(f,p,"Patient",2)==0)run(f,()->{int q=Integer.parseInt(age.getText());if(old==null)repo.add(a,n.getText(),q,c.getText(),d.getText(),x.getText(),s.getText());else repo.update(a,old.id(),n.getText(),q,c.getText(),d.getText(),x.getText(),s.getText());refresh.run();});}
 private void account(JFrame f,AuthService.User a,boolean head){JTextField u=new JTextField(),n=new JTextField();JPasswordField p=new JPasswordField();JPanel x=form(head?"Create Head Doctor":"Create user",new JLabel("Username"),u,new JLabel("Name"),n,new JLabel("Password"),p);if(JOptionPane.showConfirmDialog(f,x,"Account",2)==0)run(f,()->{if(head)auth.createHeadDoctor(u.getText(),n.getText(),p.getPassword());else auth.createUser(a,u.getText(),n.getText(),p.getPassword());});}
 private static JPanel form(String title,Object... items){JPanel p=new JPanel(new GridLayout(0,2,8,8));p.setBorder(BorderFactory.createTitledBorder(title));for(Object i:items)p.add((Component)i);return p;}private static void run(Component c,Task t){try{t.run();}catch(Exception e){error(c,e);}}private static void error(Component c,Exception e){JOptionPane.showMessageDialog(c,e.getMessage()==null?e.toString():e.getMessage(),"MediCare Pro",0);}@FunctionalInterface private interface Task{void run()throws Exception;}
}
